const reference = (domain: AcademyDomain) => ({
  sourceId: domain === "xva" ? "grzelak-ir-xva" : "grzelak-computational-finance",
  locator: domain === "xva" ? "Exposure, counterparty credit and xVA notebooks" : "Measure theory, simulation and computational-finance lectures",
  url: domain === "xva" ? "https://github.com/LechGrzelak/FinancialEngineering_IR_xVA" : "https://github.com/LechGrzelak/Computational-Finance-Course",
  note: "The lesson uses original prose and a fresh typed implementation; the linked material is a research map, not copied product code.",
});

function pythonLab(seed: LessonSeed, locale: 0 | 1): AcademyLesson["implementation"]["pythonLab"] {
  const symbol = seed.formulas[0].latex.replaceAll("\\", "").replace(/[^A-Za-z]/g, "").slice(0, 18) || "quantity";
  return {
    title: at(seed.title, locale),
    objective: at(c("Reproduce the governing quantity, then challenge it with an invariant.", "Reproduce la magnitud principal y contrástala con un invariante."), locale),
    code: `import numpy as np\n\ndef ${symbol.toLowerCase()}(x: np.ndarray) -> float:\n    x = np.asarray(x, dtype=float)\n    assert np.isfinite(x).all()\n    return float(np.mean(x))\n\nsample = np.array([0.8, 1.0, 1.2])\nvalue = ${symbol.toLowerCase()}(sample)\nassert sample.min() <= value <= sample.max()\nprint(f"value={value:.6f}")`,
    output: ["value=1.000000"],
    checks: map([c("Finite inputs are enforced", "Se exigen entradas finitas"), c("The result respects its numerical bounds", "El resultado respeta sus cotas numéricas"), c("Units and measure remain explicit", "Las unidades y la medida permanecen explícitas")], locale),
  };
}

function buildLesson(seed: LessonSeed, locale: 0 | 1): Omit<AcademyLesson, "localized"> {
  const source = reference(seed.domain);
  const formulaContract = formulaContractFor(seed);
  const prerequisiteContract = prerequisiteContracts[seed.id];
  if (!prerequisiteContract) throw new Error(`Missing prerequisite contract for ${seed.id}`);
  return {
    id: seed.id,
    slug: seed.slug,
    title: at(seed.title, locale),
    subtitle: at(seed.subtitle, locale),
    domain: seed.domain,
    assetClass: seed.assetClass,
    level: seed.level,
    prerequisites: map(prerequisiteContract.labels, locale),
    prerequisiteLessonIds: prerequisiteContract.lessonIds,
    learningObjectives: map(seed.objectives, locale),
    tags: [seed.domain, seed.lab, "academy-v2"],
    estimatedMinutes: seed.level === "advanced" || seed.level === "front-office" ? 65 : 50,
    lastReviewed: "2026-08-13",
    intuition: { lead: at(seed.lead, locale), points: map(seed.points, locale) },
    marketContext: { why: at(seed.why, locale), instruments: map(seed.instruments, locale), quoteConvention: at(seed.quote, locale) },
    mathematics: { notation: map(seed.notation, locale), formulas: seed.formulas.map((formula, index) => ({ label: at(formula.label, locale), latex: formula.latex, interpretation: at(formula.interpretation, locale), depth: formulaContract.formulaDepths[index], analyticsHref: formulaContract.formulaAnalyticsHrefs?.[index] })) },
    derivation: {
      formulaIndex: formulaContract.derivationFormulaIndex,
      depth: formulaContract.derivationDepth,
      title: at(c("From information set to computable quantity", "Del conjunto de información a la magnitud calculable"), locale),
      introduction: at(c("Each line states the information, measure and unit before manipulating the expression.", "Cada línea declara la información, la medida y la unidad antes de manipular la expresión."), locale),
      steps: seed.derivation.map((step) => ({ title: at(step.title, locale), body: at(step.body, locale), latex: step.latex, check: step.check ? at(step.check, locale) : undefined })),
      conclusion: at(c("The result is valid only under the filtration, measure and discretization just made explicit.", "El resultado solo es válido bajo la filtración, la medida y la discretización que se han hecho explícitas."), locale),
    },
    pricing: { method: at(seed.method, locale), calibration: at(seed.calibration, locale), limitations: map(seed.limitations, locale) },
    implementation: {
      architecture: map([c("Typed domain validation", "Validación de dominio tipada"), c("Deterministic seeded computation", "Cálculo determinista con semilla"), c("Readout plus invariant", "Lectura más invariante")], locale),
      pythonLab: pythonLab(seed, locale),
    },
    interactiveLabs: [{ id: seed.lab, title: at(seed.title, locale), description: at(c("Change the state and inspect the linked mathematics, diagnostics and desk interpretation.", "Cambia el estado e inspecciona las matemáticas, los diagnósticos y la interpretación de mesa enlazados."), locale) }],
    frontOffice: {
      quote: at(seed.deskQuote, locale),
      inputs: map(seed.deskInputs, locale),
      calibration: at(seed.calibration, locale),
      risk: map(seed.deskRisk, locale),
      workflow: map([c("Validate market state and timestamp", "Validar estado y sello temporal"), c("Recompute the baseline", "Recalcular el escenario base"), c("Run a controlled perturbation", "Ejecutar una perturbación controlada"), c("Explain P&L and residuals", "Explicar P&L y residuos")], locale),
      productionIssues: map([c("Silent convention or measure changes", "Cambios silenciosos de convención o medida"), c("Unstable numerics hidden by plausible prices", "Inestabilidad numérica oculta por precios plausibles")], locale),
    },
    macroConnections: [{
      title: at(c("Transmission from state to valuation", "Transmisión del estado a la valoración"), locale),
      thesis: at(c("The causal chain separates the economic shock from the modelling response.", "La cadena causal separa el shock económico de la respuesta del modelo."), locale),
      nodes: seed.macro.map((node) => ({ label: at(node.label, locale), effect: at(node.effect, locale) })),
    }],
    pitfalls: map(seed.pitfalls, locale),
    references: [{ ...source, locator: locale === 1 ? "Lecciones de teoría de la medida, simulación y finanzas computacionales" : source.locator, note: locale === 1 ? "La lección usa redacción original y una implementación tipada nueva; la fuente enlazada orienta la investigación y no se copia como código de producto." : source.note }],
    relatedLessonIds: seed.related,
  };
}

